<script setup lang="ts">
type Rule = { id:number; name:string; timing_type:'relative'|'fixed_local'; minutes_before:number|null; local_time:string|null; recipients:string[]; modes:string[]|null; template:string; quiet_start:string|null; quiet_end:string|null; is_active:boolean; max_attempts:number; retry_delay_seconds:number };
const { request } = useAdminApi();
const tab = ref('rules'), loading = ref(false), busy = ref(false), error = ref(''), success = ref('');
const rules = ref<Rule[]>([]), scheduled = ref<any[]>([]), history = ref<any[]>([]), attempts = ref<any[]>([]), attemptsFor = ref<number|null>(null), preview = ref('');
const page = ref(1), totalPages = ref(1), statusFilter = ref('');
const smsProvider=ref<any>(null),providerBusy=ref(false),driver=ref('log');
const dialog = ref(false), editing = ref<Rule|null>(null);
const blank = ():Rule => ({ id:0,name:'',timing_type:'relative',minutes_before:1440,local_time:null,recipients:['client'],modes:null,template:'سلام {{client_name}}، یادآوری نوبت شما در {{appointment_date}} ساعت {{appointment_time}} با {{counselor_name}}.',quiet_start:null,quiet_end:null,is_active:false,max_attempts:3,retry_delay_seconds:300 });
const form = reactive<Rule>(blank());
const reminderStatuses = ['pending','queued','sending','simulated','sent','failed','cancelled','skipped','not_configured'];
const label = (s:string) => ({pending:'در انتظار',queued:'در صف',sending:'در حال ارسال',simulated:'شبیه‌سازی‌شده',sent:'ارسال‌شده',failed:'ناموفق',cancelled:'لغوشده',skipped:'ردشده',not_configured:'ارائه‌دهنده تنظیم نشده'} as Record<string,string>)[s] || s || '—';
const pageData = (r:any) => r?.data?.data || r?.data || [];
const pageCount = (r:any) => Number(r?.data?.last_page || r?.last_page || 1);
function errorText(e:any) { const errors=e?.data?.errors; return errors ? Object.values(errors).flat().join(' · ') : e?.data?.message || 'عملیات انجام نشد. اتصال و دسترسی را بررسی کنید.'; }
async function load() {
  loading.value=true; error.value='';
  try {
    if(tab.value==='rules') { const [rulesResult,providerResult]:any[]=await Promise.all([request('/admin/settings/sms-reminders/rules?per_page=50'),request('/admin/settings/sms')]);rules.value=pageData(rulesResult);smsProvider.value=providerResult.data||{};driver.value=smsProvider.value.driver||'log'; }
    else { const qs=new URLSearchParams({page:String(page.value),per_page:'20'}); if(statusFilter.value) qs.set('status',statusFilter.value); const route=tab.value==='scheduled'?'scheduled':'history'; const r=await request<any>(`/admin/settings/sms-reminders/${route}?${qs}`); const rows=pageData(r); totalPages.value=pageCount(r); if(route==='scheduled') scheduled.value=rows; else history.value=rows; }
  } catch(e:any) { error.value=errorText(e); }
  finally { loading.value=false; }
}
function openRule(rule?:Rule) { editing.value=rule||null; Object.assign(form,rule?{...rule,recipients:[...(rule.recipients||[])],modes:rule.modes?[...rule.modes]:null}:blank()); dialog.value=true; }
async function saveRule() {
 if(busy.value)return; busy.value=true; error.value=''; success.value='';
 try { const body:any={...form}; delete body.id; if(body.timing_type==='relative') body.local_time=null; else body.minutes_before=null; if(!body.quiet_start&&!body.quiet_end){body.quiet_start=null;body.quiet_end=null;} await request(`/admin/settings/sms-reminders/rules${editing.value?`/${editing.value.id}`:''}`,{method:editing.value?'PATCH':'POST',body}); dialog.value=false; success.value='قاعدهٔ یادآوری ذخیره شد.'; await load(); }
 catch(e:any){error.value=errorText(e);} finally{busy.value=false;}
}
async function setEnabled(rule:Rule, enabled:boolean) { if(busy.value)return; busy.value=true; error.value=''; try { await request(`/admin/settings/sms-reminders/rules/${rule.id}`,{method:'PATCH',body:{is_active:enabled}}); success.value=enabled?'قاعده فعال شد.':'قاعده غیرفعال شد.'; await load(); } catch(e:any){error.value=errorText(e);} finally{busy.value=false;} }
async function removeRule(rule:Rule) { if(!confirm('حذف قاعده؟ اگر سابقهٔ ارسال داشته باشد، backend حذف را رد می‌کند؛ در آن صورت قاعده را غیرفعال کنید.'))return; busy.value=true; try{await request(`/admin/settings/sms-reminders/rules/${rule.id}`,{method:'DELETE'});success.value='قاعده حذف شد.';await load();}catch(e:any){error.value=errorText(e);}finally{busy.value=false;} }
async function previewRule(rule:Rule) { const booking=window.prompt('شناسهٔ رزرو برای پیش‌نمایش پیام را وارد کنید.'); if(!booking||!/^\d+$/.test(booking))return; busy.value=true; try{const r:any=await request(`/admin/settings/sms-reminders/rules/${rule.id}/preview`,{method:'POST',body:{booking_id:Number(booking)}});preview.value=r?.data?.message||'';}catch(e:any){error.value=errorText(e);}finally{busy.value=false;} }
async function loadAttempts(row:any) { busy.value=true; attemptsFor.value=row.id; try{const r:any=await request(`/admin/settings/sms-reminders/attempts?reminder_id=${row.id}&per_page=50`);attempts.value=pageData(r);}catch(e:any){error.value=errorText(e);}finally{busy.value=false;} }
async function saveDriver(){if(providerBusy.value)return;providerBusy.value=true;error.value='';try{const r:any=await request('/admin/settings/sms',{method:'PUT',body:{driver:driver.value}});smsProvider.value=r.data||{};success.value='تنظیم driver پیامک ذخیره شد؛ ارسال واقعی همچنان غیرفعال است.';}catch(e:any){error.value=errorText(e);driver.value=smsProvider.value?.driver||'log';}finally{providerBusy.value=false;}}
async function reminderAction(row:any,action:'retry'|'cancel') { if(busy.value)return; busy.value=true; error.value='';try{await request(`/admin/settings/sms-reminders/${row.id}/${action}`,{method:'POST'});success.value=action==='retry'?'تلاش مجدد ثبت شد؛ ارسال واقعی به پیکربندی provider وابسته است.':'یادآوری لغو شد.';await load();}catch(e:any){error.value=errorText(e);}finally{busy.value=false;} }
watch([tab,page,statusFilter],load); onMounted(load);
</script>

<template>
 <main dir="rtl" class="admin-page">
  <header class="admin-page__header"><div><div class="admin-eyebrow">اتوماسیون پیامک</div><h1>یادآوری‌های نوبت</h1><p>قواعد در زمان تهران زمان‌بندی می‌شوند؛ driver فعلی log است و پیام واقعی ارسال نمی‌کند.</p></div><v-btn v-if="tab==='rules'" color="primary" prepend-icon="mdi-plus" @click="openRule()">قاعدهٔ جدید</v-btn><v-btn variant="tonal" prepend-icon="mdi-refresh" :loading="loading" @click="load">به‌روزرسانی</v-btn></header>
  <v-alert type="warning" variant="tonal" class="mb-4">وضعیت provider: ارسال واقعی پیامک غیرفعال است. وضعیت‌های log یا fake اثبات ارسال به مخاطب نیستند؛ retry فقط مجدداً job را در صف backend قرار می‌دهد.</v-alert>
  <v-card v-if="tab==='rules'&&smsProvider" class="pa-4 mb-4"><div class="d-flex flex-wrap justify-space-between align-center ga-4"><div><h3>وضعیت سرویس پیامک</h3><p class="mb-0">driver: <strong>{{smsProvider.driver}}</strong> · تحویل واقعی: <strong>{{smsProvider.real_delivery_enabled?'فعال':'غیرفعال'}}</strong> · محیط fake: {{smsProvider.fake_available?'مجاز در این محیط':'غیرفعال'}}</p></div><div class="d-flex align-center ga-2"><v-select v-model="driver" style="min-width:190px" :items="[{title:'ثبت در log (بدون ارسال)',value:'log'},...(smsProvider.fake_available?[{title:'شبیه‌سازی fake',value:'fake'}]:[])]" label="driver" hide-details/><v-btn variant="tonal" :loading="providerBusy" :disabled="driver===smsProvider.driver" @click="saveDriver">ذخیره driver</v-btn></div></div></v-card>
  <v-alert v-if="error" type="error" variant="tonal" class="mb-3" closable @click:close="error=''">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-3" closable @click:close="success=''">{{success}}</v-alert>
  <v-tabs v-model="tab" class="mb-4"><v-tab value="rules">قواعد</v-tab><v-tab value="scheduled">زمان‌بندی‌شده</v-tab><v-tab value="history">تاریخچه و تحویل</v-tab></v-tabs>
  <v-card v-if="tab==='rules'" class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>قاعده</th><th>زمان‌بندی</th><th>مخاطب</th><th>حالت جلسه</th><th>ساعات سکوت</th><th>وضعیت</th><th>اقدام</th></tr></thead><tbody><tr v-for="r in rules" :key="r.id"><td>{{r.name}}</td><td>{{r.timing_type==='relative'?`${r.minutes_before} دقیقه قبل`:`روز نوبت، ساعت ${r.local_time} (تهران)`}}</td><td>{{r.recipients.join('، ')}}</td><td>{{r.modes?.join('، ')||'همه'}}</td><td>{{r.quiet_start&&r.quiet_end?`${r.quiet_start} تا ${r.quiet_end}`:'—'}}</td><td><v-switch :model-value="r.is_active" :disabled="busy" hide-details color="success" @update:model-value="setEnabled(r,!!$event)"/></td><td class="text-no-wrap"><v-btn size="small" variant="text" @click="previewRule(r)">پیش‌نمایش</v-btn><v-btn size="small" variant="text" @click="openRule(r)">ویرایش</v-btn><v-btn size="small" variant="text" color="error" @click="removeRule(r)">حذف</v-btn></td></tr><tr v-if="!loading&&!rules.length"><td colspan="7"><div class="admin-empty-state">قاعده‌ای وجود ندارد. با ایجاد قاعده، ابتدا غیرفعال ذخیره می‌شود.</div></td></tr></tbody></v-table></div></v-card>
  <template v-else><v-row class="mb-2"><v-col cols="12" md="4"><v-select v-model="statusFilter" :items="reminderStatuses" item-title="title" :item-value="v=>v" label="وضعیت" clearable><template #item="{props,item}"><v-list-item v-bind="props" :title="label(item.raw)"/></template><template #selection="{item}">{{label(item.raw)}}</template></v-select></v-col></v-row><v-card class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>رزرو</th><th>قاعده</th><th>گیرنده</th><th>زمان مقرر</th><th>وضعیت</th><th>تلاش</th><th>اقدام</th></tr></thead><tbody><tr v-for="r in (tab==='scheduled'?scheduled:history)" :key="r.id"><td>{{r.booking_id}}</td><td>{{r.rule_id}}</td><td>{{r.recipient_type}} · {{r.phone||'شماره ثبت نشده'}}</td><td>{{r.scheduled_at||r.sent_at||'—'}}</td><td>{{label(r.status)}}</td><td>{{r.retry_attempts??r.attempt_count??'—'}}</td><td><v-btn v-if="r.status==='pending'" size="small" :disabled="busy" @click="reminderAction(r,'cancel')">لغو</v-btn><v-btn v-if="['failed','not_configured'].includes(r.status)" size="small" :disabled="busy" @click="reminderAction(r,'retry')">تلاش مجدد</v-btn><v-btn size="small" variant="text" @click="loadAttempts(r)">جزئیات تلاش‌ها</v-btn></td></tr><tr v-if="!loading&&!(tab==='scheduled'?scheduled:history).length"><td colspan="7"><div class="admin-empty-state">رکوردی با این فیلتر یافت نشد.</div></td></tr></tbody></v-table></div><div v-if="totalPages>1" class="admin-table-pagination"><v-btn :disabled="page<=1" @click="page--">قبلی</v-btn><span>صفحه {{page}} از {{totalPages}}</span><v-btn :disabled="page>=totalPages" @click="page++">بعدی</v-btn></div></v-card></template>
  <v-dialog v-model="dialog" max-width="850" scrollable><v-card class="pa-5" dir="rtl"><h2 class="mb-4">{{editing?'ویرایش قاعده':'قاعدهٔ جدید'}}</h2><v-text-field v-model="form.name" label="نام قاعده"/><v-row><v-col cols="12" md="6"><v-select v-model="form.timing_type" :items="[{title:'چند دقیقه/ساعت قبل',value:'relative'},{title:'ساعت محلی روز نوبت',value:'fixed_local'}]" label="نوع زمان‌بندی"/></v-col><v-col v-if="form.timing_type==='relative'" cols="12" md="6"><v-text-field v-model.number="form.minutes_before" type="number" min="0" max="43200" label="چند دقیقه قبل از شروع" hint="مثال: ۱۴۴۰ برای ۲۴ ساعت قبل" persistent-hint/></v-col><v-col v-else cols="12" md="6"><v-text-field v-model="form.local_time" type="time" label="ساعت تهران در روز نوبت"/></v-col></v-row><v-select v-model="form.recipients" multiple chips :items="[{title:'مراجع',value:'client'},{title:'مشاور',value:'counselor'},{title:'پذیرش',value:'reception'}]" label="گیرندگان"/><v-select v-model="form.modes" multiple chips clearable :items="[{title:'حضوری',value:'in_person'},{title:'آنلاین',value:'meet'},{title:'تلفنی',value:'voice_call'}]" label="حالت جلسه (خالی = همه)"/><v-textarea v-model="form.template" label="قالب پیام" rows="4"/><div class="text-caption mb-3">متغیرها: <code v-pre>{{client_name}}, {{counselor_name}}, {{appointment_date}}, {{appointment_time}}, {{session_type}}, {{center_name}}, {{booking_reference}}, {{center_address}}, {{service_name}}</code></div><v-row><v-col cols="6"><v-text-field v-model="form.quiet_start" type="time" label="شروع ساعات سکوت (اختیاری)"/></v-col><v-col cols="6"><v-text-field v-model="form.quiet_end" type="time" label="پایان ساعات سکوت (اختیاری)"/></v-col><v-col cols="6"><v-text-field v-model.number="form.max_attempts" type="number" min="1" max="8" label="حداکثر تلاش"/></v-col><v-col cols="6"><v-text-field v-model.number="form.retry_delay_seconds" type="number" min="30" label="فاصله تلاش مجدد (ثانیه)"/></v-col></v-row><v-switch v-model="form.is_active" label="فعال‌سازی قاعده"/><div class="d-flex ga-2"><v-btn color="primary" :loading="busy" :disabled="!form.name.trim()||!form.template.trim()||!form.recipients.length||(form.timing_type==='relative'&&form.minutes_before===null)||(form.timing_type==='fixed_local'&&!form.local_time)||Boolean(form.quiet_start)!==Boolean(form.quiet_end)" @click="saveRule">ذخیره</v-btn><v-btn variant="text" @click="dialog=false">انصراف</v-btn></div></v-card></v-dialog>
  <v-dialog :model-value="!!preview" max-width="600" @update:model-value="v=>{if(!v)preview=''}"><v-card class="pa-5" dir="rtl"><h3>پیش‌نمایش پیام</h3><p class="my-4" style="white-space:pre-wrap">{{preview}}</p><v-btn @click="preview=''">بستن</v-btn></v-card></v-dialog>
  <v-dialog :model-value="attemptsFor!==null" max-width="800" @update:model-value="v=>{if(!v)attemptsFor=null}"><v-card class="pa-5" dir="rtl"><h3>تلاش‌های ارسال</h3><v-table><thead><tr><th>شماره</th><th>وضعیت</th><th>provider</th><th>خطا</th><th>زمان</th></tr></thead><tbody><tr v-for="a in attempts" :key="a.id"><td>{{a.attempt_number}}</td><td>{{label(a.status)}}</td><td>{{a.provider||'—'}}</td><td>{{a.error_message||'—'}}</td><td>{{a.created_at}}</td></tr><tr v-if="!attempts.length"><td colspan="5">تلاشی ثبت نشده است.</td></tr></tbody></v-table><v-btn class="mt-3" @click="attemptsFor=null">بستن</v-btn></v-card></v-dialog>
 </main>
</template>
